"""Source-recovery guard tests; generated bytes only, no credentials or recordings."""
from pathlib import Path
import tempfile
import unittest
from create_checkpoint import source_path


class RecoveryTests(unittest.TestCase):
    def test_source_and_license_text_allowed(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            for name in ("Main.kt", "README.md", "notice.txt", "state.json"):
                (root / name).write_text("generated source", encoding="utf-8")
                self.assertEqual(source_path(name, root), root / name)

    def test_case_insensitive_artifacts_secrets_and_caches_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            for name in ("audio.WAV", "audio.OpUs", "model.ONNX", "signing.P12", "runtime.AAR",
                         "weights.GGUF", "source.ZIP", "token.KEY", ".env", ".env.local", "secrets.JSON",
                         ".LOCAL/note.md", "app/build/note.md", "../outside.md", "C:/outside.md"):
                with self.subTest(name=name), self.assertRaises(AssertionError):
                    source_path(name, root)

    def test_disguised_binary_and_oversized_source_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            candidate = root / "data.json"
            for body in (b"binary\0data", b"\xff", b"x" * (2 * 1024 * 1024 + 1)):
                candidate.write_bytes(body)
                with self.assertRaises((AssertionError, UnicodeDecodeError)):
                    source_path("data.json", root)

    def test_outside_symlink_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory) / "root"
            root.mkdir()
            outside = Path(directory) / "outside.md"
            outside.write_text("generated outside file")
            try:
                (root / "linked.md").symlink_to(outside)
            except OSError:
                self.skipTest("OS does not permit test symlinks")
            with self.assertRaises(AssertionError):
                source_path("linked.md", root)


if __name__ == "__main__":
    unittest.main()
